mapper.sql:
WITH ranked_reviews AS ( SELECT request_id,merchant_id,statement_id,order_id,difference_kind,decision,reviewed_at, ROW_NUMBER() OVER ( PARTITION BY merchant_id,statement_id,order_id,order_line_id,difference_kind,evidence_reference ORDER BY reviewed_at DESC,request_id DESC ) AS review_rank FROM merchant_statement_difference_reviews
AND merchant_id=#{merchant} AND order_id=#{filter.orderId}
), work AS ( SELECT 'STATEMENT_DIFFERENCE' AS kind,r.request_id AS source_id,r.merchant_id,r.statement_id,r.order_id, r.difference_kind AS reason_code, CASE WHEN r.difference_kind IN ('PAYOUT_FAILED','PAYOUT_AMOUNT','MULTIPLE_PAYOUTS','PAYOUT_CURRENCY') THEN 'HIGH' ELSE 'NORMAL' END AS priority, CASE WHEN d.closed_at IS NOT NULL THEN 'CLOSED' WHEN d.receipt IS NULL THEN 'WAITING_EVIDENCE' ELSE 'OPEN' END AS state, COALESCE(d.closed_at,d.linked_at,r.reviewed_at) AS updated_at FROM ranked_reviews r LEFT JOIN merchant_statement_difference_dispositions d ON d.review_id=r.request_id WHERE r.review_rank=1 AND r.decision='CONFIRMED' UNION ALL SELECT 'RETURN_WORK',w.case_id,s.merchant_id,NULL,s.order_id,w.warehouse_status, CASE WHEN w.warehouse_status IN ('SHORT_RECEIVED','FAILED') THEN 'HIGH' ELSE 'NORMAL' END, CASE WHEN w.phase IN ('APPROVED','REJECTED') THEN 'CLOSED' ELSE w.phase END,w.updated_at FROM return_exception_work_orders w JOIN line_after_sales s ON s.id=w.case_id
AND s.merchant_id=#{merchant} AND s.order_id=#{filter.orderId}
)
